/*
 * We convert as.c into a header file to make convenient for fuzzing.
 * We do this for several of the binutils applications when creating
 * the binutils fuzzers.
 */
#include <fuzz_as.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  char filename[256];
  sprintf(filename, "/tmp/libfuzzer-%d.s", getpid());
  FILE *fp = fopen(filename, "wb");
  if (!fp) {
    return 0;
  }
  fwrite(data, size, 1, fp);
  fclose(fp);

  reg_section = NULL;

  const char *fakeArgv[3];
  fakeArgv[0] = "fuzz_objdump";
  fakeArgv[1] = filename; // Assemble our fake source file.
  fakeArgv[2] = NULL;

  out_file_name = "/tmp/tmp-out";

  // as initialition. This follows the flow of ordinary main function
  symbol_begin ();
  frag_init ();
  subsegs_begin ();
  read_begin ();
  input_scrub_begin ();
  expr_begin ();
  output_file_create (out_file_name);
  itbl_init ();
  dwarf2_init ();
  cond_finish_check (-1);

  dot_symbol_init ();

  // Main fuzzer target. Assemble our random data.
  perform_an_assembly_pass (2, (char**)fakeArgv);

  // Cleanup
  cond_finish_check (-1);
  dwarf2_finish ();
  cfi_finish ();
  input_scrub_end ();

  unlink(filename);

  return 0;
}

	      /* In DWARF-5 the 0 entry in the directory table is
		 expected to be the same as the DW_AT_comp_dir (which
		 is set to the current build directory).  Since we are
		 about to create a directory entry that is not the
		 same, allocate the current directory first.
